// Writes Blade components generated by static/formats.js for tests/php/blade-test.php.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';

globalThis.window = globalThis;
const require = createRequire(import.meta.url);
require('../../static/icons.js');
require('../../static/formats.js');
const { SvgFormats } = globalThis;

const texts = [
    '{{ $evil }}', '{!! $raw !!}', '@if(true) x @endif', 'user@example.com', '@{{ literal }}', 'a @ b', '@@twice',
    '(@media x)', '@', 'x@', '$attributes', '{{-- c --}}', '@verbatim', '{ single }', 'line1\n  line2\twith tab',
    '<tspan>@php echo 1; @endphp</tspan>', '{{$x}}{{$y}}',
];
const out = new URL('./build/views/components/', import.meta.url);
mkdirSync(out, { recursive: true });
texts.forEach((t, i) => {
    writeFileSync(new URL(`case${i}.blade.php`, out), SvgFormats.convert('blade', `<svg xmlns="http://www.w3.org/2000/svg"><text>${t}</text></svg>`));
});
const real = readFileSync(new URL('../fixtures/python.svg', import.meta.url), 'utf8').trim();
writeFileSync(new URL('real.blade.php', out), SvgFormats.convert('blade', real));
writeFileSync(new URL('./build/real.expected.svg', import.meta.url), real.replace('<svg', '<svg class="size-6"'));
writeFileSync(new URL('./build/cases.json', import.meta.url), JSON.stringify(texts));
console.log(`Wrote ${texts.length + 1} Blade components`);
